  "stuSess.creditAppliedSuccess": "K vašemu zůstatku byl připsán kredit €{amount}, který se automaticky použije na další lekci.",
  "stuSess.refundContactNote": "Pro vrácení platby kontaktujte <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Máte dotazy nebo potíže? Kontaktujte <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Vrácení platby bylo zahájeno přes Stripe.</p><p class=\"text-emerald-800 mt-1\">Vrácené platby kartou obvykle dorazí přibližně do <strong>5–10 pracovních dní</strong> (záleží na bance). Pokud platbu v obvyklé lhůtě neobdržíte, napište na <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Zdá se, že tato lekce nebyla uhrazena přes Stripe v Tutlio (např. bankovním převodem nebo hotově). Automatické vrácení platby zde není dostupné.</p><p class=\"mt-2\">Vrácení platby domluvte s lektorem <strong>{tutor}</strong> — použijte e-mail nebo kontakty z rezervací či přímo od lektora.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Zdá se, že tato lekce nebyla uhrazena přes Stripe v Tutlio (např. bankovním převodem nebo hotově). Automatické vrácení platby zde není dostupné.</p><p class=\"mt-2\">Protože studujete prostřednictvím organizace, kontaktujte <strong>správce organizace</strong> přes lektora nebo zveřejněné kontakty organizace.</p>",
