  "landing.faq.whatIsQ": "Co je Tutlio?",
  "landing.faq.whatIsA": "Tutlio je platforma pro správu doučování, která samostatným lektorům a doučovacím školám pomáhá spravovat rozvrhy, platby, komunikaci se studenty a evidenci lekcí na jednom místě.",
  "landing.faq.whoForQ": "Pro koho je Tutlio určeno?",
  "landing.faq.whoForA": "Tutlio je určeno samostatným lektorům, učitelům hudby, jazyků a matematiky, doučovacím školám a vzdělávacím centrům všech velikostí.",
  "landing.faq.waitlistQ": "Jak funguje čekací listina studentů?",
  "landing.faq.waitlistA": "Když student lekci zruší, uvolněný termín se automaticky nabídne studentům na čekací listině. Místo získá ten, kdo ho potvrdí jako první - lektoři tak nepřicházejí o příjmy kvůli zrušeným lekcím.",
  "landing.faq.freeTrialQ": "Je k dispozici zkušební období zdarma?",
  "landing.faq.freeTrialA": "Ano! Každý nový účet automaticky získá 7 dní zdarma - bez kódu. Během zkušebního období nic neplatíte a můžete kdykoli zrušit.",
