  "orgTutorPolicy.title": "Interní pravidla pro lektory",
  "orgTutorPolicy.intro": "Před používáním platformy si prostudujte interní pravidla organizace.",
  "orgTutorPolicy.acceptBtn": "Rozumím",
  "orgTutorPolicy.viewBtn": "Zobrazit interní pravidla",
  "orgTutorPolicy.s1Title": "1. Obecná ustanovení",
  "orgTutorPolicy.s1Body": "Tato pravidla upravují používání platformy Tutlio (dále jen „Platforma“) učitelem nebo lektorem (dále jen „Lektor“). K používání Platformy vás pozvala vzdělávací agentura, škola nebo doučovací centrum, které zastupujete (dále jen „Organizace“). Technický provoz a podporu Platformy zajišťuje MB Tutlio. Používáním účtu souhlasíte s těmito pravidly a zásadami ochrany osobních údajů.",
  "orgTutorPolicy.s2Title": "2. Správa účtu a rozvrhů",
  "orgTutorPolicy.s2Intro": "Platforma je navržena tak, abyste nemuseli trávit čas domlouváním termínů lekcí se studenty.",
  "orgTutorPolicy.s2Link": "Jedinečný odkaz: Je vám přiřazen osobní rezervační odkaz podle vyučovaných předmětů, přes který si studenti plánují lekce.",
  "orgTutorPolicy.s2Calendar": "Synchronizace kalendáře: Vaše dostupnost přímo závisí na propojení s Google Calendar (synchronizace ve 2 směrech). Osobně odpovídáte za správnost a aktuálnost volných termínů v kalendáři. Platforma studentům neumožní rezervovat časy označené v kalendáři jako obsazené.",
  "orgTutorPolicy.s2Security": "Zabezpečení účtu: Váš účet je osobní. Přihlašovací údaje musíte chránit a nesmíte je sdílet s třetími stranami.",
  "orgTutorPolicy.s3Title": "3. Rušení lekcí a čekací listina",
  "orgTutorPolicy.s3Intro": "Platforma pomáhá využít rozvrh naplno a omezit prázdné termíny:",
  "orgTutorPolicy.s3Auto": "Pokud student lekci zruší, Platforma automaticky pošle upozornění (SMS/e-mail) ostatním studentům na vaší čekací listině a nabídne jim uvolněný termín. Z vaší strany není potřeba žádný další krok.",
  "orgTutorPolicy.s3Rules": "Pravidla rušení lekcí (předstih zrušení a jeho důsledky) určuje vaše Organizace.",
  "orgTutorPolicy.s4Title": "4. Finance a platby",
  "orgTutorPolicy.s4Intro": "Nemusíte se starat o fakturaci ani vybírání plateb od rodičů:",
  "orgTutorPolicy.s4Advance": "Všechny platby studentů nebo rodičů za vaše lekce se vybírají předem přes Platformu a převádějí přímo vaší Organizaci.",
  "orgTutorPolicy.s4Confirmed": "Lekci odučíte pouze tehdy, když je v systému potvrzena (tedy již byla uhrazena).",
  "orgTutorPolicy.s4Contact": "Ohledně odměny, termínů výplat a dalších finančních záležitostí se obraťte přímo na správce své Organizace. MB Tutlio s Lektory neprovádí žádné přímé finanční transakce.",
  "orgTutorPolicy.s5Title": "5. Ochrana osobních údajů studentů (GDPR)",
  "orgTutorPolicy.s5Intro": "Jako Lektor máte přístup k osobním údajům studentů, interním poznámkám a výukovým materiálům. Zavazujete se:",
  "orgTutorPolicy.s5Use": "Používat tato data výhradně k organizaci a vedení lekcí.",
  "orgTutorPolicy.s5NoCopy": "Nekopírovat, neexportovat ani nešířit kontaktní údaje studentů a rodičů mimo Platformu.",
  "orgTutorPolicy.s5Notes": "Chránit interní záznamy Organizace (poznámky o pokroku studentů), které vidíte pouze vy a správa Organizace, nikoli studenti nebo rodiče.",
  "orgTutorPolicy.s5Termination": "Po ukončení pracovního vztahu s Organizací vám bude přístup k těmto datům okamžitě odebrán.",
  "orgTutorPolicy.s6Title": "6. Technický provoz a omezení odpovědnosti",
  "orgTutorPolicy.s6Body": "Je zakázáno používat Platformu k protiprávním účelům, šířit škodlivé odkazy ve výukových materiálech nebo jinak narušovat systém. MB Tutlio zajišťuje provoz a technickou údržbu Platformy, ale neodpovídá za výpadky způsobené vaším internetovým připojením, poruchami zařízení nebo nesprávným nastavením Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Podpora a kontakty",
  "orgTutorPolicy.s7Org": "S dotazy k rozvrhům, odměnám, přiřazování studentů nebo organizaci práce se obraťte na správce své Organizace.",
  "orgTutorPolicy.s7Tech": "Technické chyby Platformy (nefunkční synchronizace kalendáře, nedoručená upozornění) nahlaste správci své Organizace, který kontaktuje technickou podporu Tutlio.",
  "register.orgPolicyConsent": "Používáním naší platformy souhlasíte s",
  "register.orgPolicyLink": "interními pravidly",
