  "quiz.offer.guarantee.body": "Pokud vám Tutlio nevyhovuje, požádejte o vrácení peněz během prvních 14 dní. Bez udání důvodu.",
  "quiz.offer.testimonials.eyebrow": "Tutlio v každodenní práci",
  "quiz.offer.testimonials.title.solo": "Čeho si všímají samostatní lektoři",
  "quiz.offer.testimonials.title.company": "Jak Tutlio podporuje doučovací organizaci",
  "quiz.offer.testimonials.title.school": "Jak Tutlio propojuje školní administrativu",
  "quiz.offer.testimonials.pause": "Pozastavit reference",
  "quiz.offer.testimonials.play": "Přehrát reference",
  "quiz.offer.testimonials.navigation": "Vybrat referenci",
  "quiz.offer.testimonials.goTo": "Zobrazit referenci {number}",
  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Lektorka chemie a biologie",
  "quiz.offer.testimonial.solo.copy3": "„Veřejná stránka a rezervace přes jeden odkaz pomáhají novým studentům rozhodnout se rychleji a já už nemusím každému zvlášť posílat stejné informace.“",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Lektor fyziky",
  "quiz.offer.testimonial.solo.copy4": "„V kalendáři hned vidím lekce, změny a stavy plateb. Každodenní administrativa je mnohem kratší a přehlednější.“",
  "quiz.offer.testimonial.company.copy1": "„Změny lekcí, komentáře lektorů a hodiny dříve přicházely v oddělených zprávách. Teď má administrativní tým úplný přehled v jednom rozvrhu.“",
  "quiz.offer.testimonial.company.name2": "Samostatné doučovací centrum",
  "quiz.offer.testimonial.company.role2": "Vlastník · 8 lektorů",
  "quiz.offer.testimonial.company.copy2": "„Dříve jsem páteční večery trávil porovnáváním kalendáře se zprávami lektorů před přípravou výplat. S Tutlio je většina těchto kontrol už hotová.“",
  "quiz.offer.testimonial.company.name3": "Jazykové studio",
  "quiz.offer.testimonial.company.role3": "Vedoucí provozu · 14 lektorů",
  "quiz.offer.testimonial.company.copy3": "„Když se lekce přesune, tým hned vidí stejnou aktualizaci. Máme méně doplňujících zpráv a rodiče dostávají mnohem jasnější odpovědi.“",
  "quiz.offer.testimonial.company.name4": "Akademie přípravy na zkoušky",
  "quiz.offer.testimonial.company.role4": "Finanční koordinátor · 22 lektorů",
  "quiz.offer.testimonial.company.copy4": "„Pravidla odměn našich lektorů se liší podle typu lekce, takže konec měsíce znamenal hodně ručního kontrolování. S Tutlio je tento proces mnohem klidnější.“",
  "quiz.offer.testimonial.school.name2": "Samostatná komunitní škola",
  "quiz.offer.testimonial.school.role2": "Koordinátor přijímání · 86 studentů",
  "quiz.offer.testimonial.school.copy2": "„Období zápisů dříve znamenalo sledovat formuláře, údaje rodičů a podepsané smlouvy v oddělených složkách. Teď náš tým sleduje každou rodinu na jednom místě.“",
