  "landing.custom.badge": "Zásadní rozdíl",
  "landing.custom.title": "Software, který se přizpůsobí vašemu způsobu práce - ne naopak",
  "landing.custom.sub": "Každá škola i agentura funguje trochu jinak. Když standardní postup nesedí, přizpůsobíme Tutlio vašemu procesu - obvykle v řádu týdnů, ne čtvrtletí. Několik věcí, které jsme už pro klienty postavili:",
  "landing.custom.ex1Title": "Roční smlouvy s elektronickým podpisem",
  "landing.custom.ex1Desc": "Soukromá škola potřebovala, aby rodiče podepisovali roční smlouvy elektronicky, platili ve splátkách a aby se každá platba objevila v exportu připraveném pro účetnictví. Celý cyklus dnes běží uvnitř Tutlia.",
  "landing.custom.ex2Title": "Pravidla odměn a provizí lektorů",
  "landing.custom.ex2Desc": "Agentura platí každého lektora podle předmětu a typu lekce a k tomu si připočítává firemní provizi. Jejich pravidla jsme namodelovali, takže měsíční výkazy lektorů i faktury vznikají automaticky.",
  "landing.custom.ex3Title": "Nabídky pro rodiče na jedno kliknutí",
  "landing.custom.ex3Desc": "Škola chtěla nabízet doplňkové lekce e-mailem a nechat rodiče přijmout je jediným kliknutím - bez účtu a bez tisku. Přijetí, vyúčtování i pozvánka na první lekci dnes probíhají samy.",
  "landing.custom.ex4Title": "Vaše značka na vašem webu",
  "landing.custom.ex4Desc": "Organizace chtěla vlastní logo a barvy a k tomu přihlášení vložené přímo do svého webu, aby studenti ani rodiče neměli pocit, že jej opustili. Tutlio dnes běží pod jejich značkou.",
  "landing.custom.note": "Nic z toho není zvláštní edice. Každá úprava se stane součástí téhož produktu, který váš tým už používá, včetně všech budoucích aktualizací.",
  "landing.custom.cta": "Řekněte nám, jak pracujete",
  "landing.custom.soloTitle": "Něco vám chybí?",
  "landing.custom.soloNote": "Pravidelně vyvíjíme funkce pro jednotlivé klienty - od jednoho platebního pravidla po celý pracovní postup. Napište nám, co by vám ušetřilo čas.",
  "stats.cancellationPartTutor": "lektor: {count}",
