  "compare.customBody": "Většinu doučovacích platforem lze nastavit, ale ne změnit. Tutlio staví a udržuje malý tým, který přenáší postupy jednotlivých zákazníků - smluvní cesty, pravidla odměňování, odkazy na potvrzení pro rodiče, portály s vaší značkou - do stejného produktu, jaký používají všichni. Pokud má vaše škola nebo agentura postup, kterým se má software řídit, postavíme ho.",
